-- Run as a schema owner; create a separate least-privilege campusos_app user for the API.
CREATE TABLE roles (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR2(40) UNIQUE NOT NULL, name VARCHAR2(80) NOT NULL);
CREATE TABLE users (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR2(120) UNIQUE NOT NULL, password_hash VARCHAR2(255) NOT NULL, display_name VARCHAR2(120) NOT NULL, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE user_roles (user_id NUMBER REFERENCES users(id), role_id NUMBER REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE campuses (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR2(120) NOT NULL);
CREATE TABLE buildings (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, campus_id NUMBER NOT NULL REFERENCES campuses(id), name VARCHAR2(120) NOT NULL, status VARCHAR2(20) DEFAULT 'HEALTHY');
CREATE TABLE rooms (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, building_id NUMBER NOT NULL REFERENCES buildings(id), name VARCHAR2(100) NOT NULL, capacity NUMBER NOT NULL CHECK(capacity>0));
CREATE TABLE assets (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_id NUMBER REFERENCES rooms(id), name VARCHAR2(120) NOT NULL, asset_type VARCHAR2(50) NOT NULL, health_score NUMBER CHECK(health_score BETWEEN 0 AND 100));
CREATE TABLE sensors (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id NUMBER REFERENCES assets(id), room_id NUMBER REFERENCES rooms(id), sensor_type VARCHAR2(40) NOT NULL, status VARCHAR2(20) DEFAULT 'ONLINE');
CREATE TABLE telemetry_readings (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sensor_id NUMBER NOT NULL REFERENCES sensors(id), metric VARCHAR2(40) NOT NULL, metric_value NUMBER NOT NULL, recorded_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE INDEX telemetry_sensor_time_ix ON telemetry_readings(sensor_id, recorded_at DESC);
CREATE TABLE anomalies (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, building_id NUMBER REFERENCES buildings(id), severity VARCHAR2(20) NOT NULL, title VARCHAR2(200) NOT NULL, evidence CLOB, confidence NUMBER CHECK(confidence BETWEEN 0 AND 100), status VARCHAR2(30) DEFAULT 'OPEN', created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE recommendations (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, anomaly_id NUMBER REFERENCES anomalies(id), title VARCHAR2(200) NOT NULL, status VARCHAR2(30) DEFAULT 'PENDING_APPROVAL', created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE work_orders (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recommendation_id NUMBER REFERENCES recommendations(id), status VARCHAR2(30) NOT NULL, assignee_id NUMBER REFERENCES users(id), due_at TIMESTAMP, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE audit_logs (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id NUMBER REFERENCES users(id), action VARCHAR2(80) NOT NULL, entity_type VARCHAR2(60) NOT NULL, entity_id NUMBER, metadata CLOB, created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
